def solution() -> int:
    # 0/1 Knapsack implementation for the given instance
    W = [17, 9, 1, 3, 14, 30, 11, 3, 25, 13, 23, 7, 14, 28, 13, 32]
    V = [7, 25, 19, 32, 2, 21, 26, 19, 2, 11, 13, 21, 9, 22, 28, 14]
    C = 16

    # Filter out items that are heavier than the capacity – they can never be taken
    items = [(w, v) for w, v in zip(W, V) if w <= C]
    n = len(items)
    # DP table: dp[i][c] = max value using first i items with capacity c
    dp = [[0] * (C + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        w, v = items[i - 1]
        for c in range(C + 1):
            if w <= c:
                dp[i][c] = max(dp[i - 1][c], dp[i - 1][c - w] + v)
            else:
                dp[i][c] = dp[i - 1][c]
    return int(dp[n][C])

