def solution() -> int:
    # Partition problem: minimize difference between two groups
    weights = [14, 7]
    total = sum(weights)
    n = len(weights)
    # Use dynamic programming to find achievable sums up to total//2
    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True
    for w in weights:
        for s in range(target, w - 1, -1):
            dp[s] = dp[s] or dp[s - w]
    # Find the best achievable sum closest to target
    for s in range(target, -1, -1):
        if dp[s]:
            best = s
            break
    diff = total - 2 * best
    return int(diff)

