    for w in weights:
        for s in range(target, w - 1, -1):
            dp[s] = dp[s] or dp[s - w]
    # Find the largest reachable sum <= target
    for s in range(target, -1, -1):
        if dp[s]:
            best = s
            break
    diff = total - 2 * best
    return int(diff)

