import heapq
from typing import List, Tuple

def solution() -> Tuple[List[int], int]:
    # graph definition (directed)
    graph = {
        0: [(1, 3), (3, 5)],
        2: [(1, 5), (0, 4)],
        3: [(1, 5)],
    }
    start, target = 0, 3
    # Dijkstra's algorithm
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    prev = {}
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == target:
            break
        for v, w in graph.get(u, []):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))
    # reconstruct path
    path = []
    node = target
    if node in dist and dist[node] != float('inf'):
        while node != start:
            path.append(node)
            node = prev[node]
        path.append(start)
        path.reverse()
    else:
        path = []
    total_distance = dist[target] if dist[target] != float('inf') else -1
    return path, total_distance

